<template><div class="page-container"><div class="page-header"><div><h2>校园会议与通知发布</h2><p>发布会议、参会反馈与结果汇总</p></div><div><span>用户ID</span><el-input-number v-model="userId" :min="1"/><el-button @click="load">刷新</el-button><el-button type="primary" @click="visible=true">发布会议</el-button></div></div>
<el-tabs><el-tab-pane label="会议列表"><el-table :data="meetings" stripe><el-table-column prop="title" label="会议主题"/><el-table-column prop="meetingDate" label="日期"/><el-table-column label="时间"><template #default="s">{{s.row.startTime}} - {{s.row.endTime}}</template></el-table-column><el-table-column prop="location" label="地点"/><el-table-column label="操作" width="260"><template #default="s"><el-button link type="success" @click="reply(s.row,'参会')">参会</el-button><el-button link type="warning" @click="reply(s.row,'请假')">请假</el-button><el-button link @click="summary(s.row)">汇总</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane :label="`我的通知 (${unread})`"><el-table :data="notifications"><el-table-column label="状态" width="70"><template #default="s"><el-badge :is-dot="s.row.isRead===0"/></template></el-table-column><el-table-column prop="title" label="标题"/><el-table-column prop="content" label="内容"/><el-table-column prop="createTime" label="时间"/><el-table-column label="操作"><template #default="s"><el-button link :disabled="s.row.isRead===1" @click="read(s.row)">标为已读</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs>
<el-dialog v-model="visible" title="发布会议通知" width="600"><el-form label-width="90"><el-form-item label="会议主题"><el-input v-model="form.title"/></el-form-item><el-form-item label="会议内容"><el-input v-model="form.content" type="textarea"/></el-form-item><el-form-item label="会议日期"><el-date-picker v-model="form.meetingDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="起止时间"><el-time-picker v-model="timeRange" is-range value-format="HH:mm:ss"/></el-form-item><el-form-item label="会议地点"><el-input v-model="form.location"/></el-form-item><el-form-item label="参会人员"><el-input v-model="attendeeText" placeholder="用户ID用逗号分隔，如：2,3,4"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="publish">发布并通知</el-button></template></el-dialog>
<el-dialog v-model="summaryVisible" title="参会情况汇总" width="420"><el-row :gutter="12"><el-col v-for="(v,k) in summaryData" :key="k" :span="8"><el-statistic :title="k" :value="v"/></el-col></el-row></el-dialog></div></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{meetingAPI}from'@/api/getData.js';const userId=ref(1),meetings=ref([]),notifications=ref([]),visible=ref(false),summaryVisible=ref(false),summaryData=ref({}),attendeeText=ref('2'),timeRange=ref([]),form=reactive({title:'',content:'',initiatorId:1,meetingDate:'',location:''});const unread=computed(()=>notifications.value.filter(v=>v.isRead===0).length);const load=async()=>{const[a,b]=await Promise.all([meetingAPI.list(),meetingAPI.notifications(userId.value)]);if(a&&a!==-1)meetings.value=a.data||[];if(b&&b!==-1)notifications.value=b.data||[]};const publish=async()=>{const ids=attendeeText.value.split(',').map(v=>Number(v.trim())).filter(Number.isInteger);const r=await meetingAPI.publish({meeting:{...form,initiatorId:userId.value,startTime:timeRange.value?.[0],endTime:timeRange.value?.[1]},attendeeIds:ids});if(r&&r!==-1){ElMessage.success('会议发布成功，通知已推送');visible.value=false;load()}};const reply=async(row,status)=>{const r=await meetingAPI.reply(row.meetingId,userId.value,status);if(r&&r!==-1)ElMessage.success(`已反馈：${status}`)};const summary=async row=>{const r=await meetingAPI.summary(row.meetingId);if(r&&r!==-1){summaryData.value=r.data;summaryVisible.value=true}};const read=async row=>{const r=await meetingAPI.readNotification(row.notifyId);if(r&&r!==-1)load()};onMounted(load);</script>
<style scoped>.page-container{padding:24px;background:#f5f7fa;min-height:100vh}.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.page-header h2{margin:0}.page-header p{color:#909399}.page-header>div:last-child{display:flex;align-items:center;gap:8px}.el-tabs{background:white;padding:16px 20px}</style>
